package com.sanitysaver;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

import java.awt.*;

@ConfigGroup("sanitysaver")
public interface SanitySaverConfig extends Config
{
    @ConfigItem(
            keyName = "censoredItems",
            name = "Censored items",
            description = "Item IDs or names to censor (comma-separated)",
            position = 0
    )
    default String censoredItems()
    {
        return "";
    }

    @ConfigItem(
            keyName = "minAmount",
            name = "Minimum amount",
            description = "Only censor stacks equal to or above this amount",
            position = 1

    )
    default int minAmount()
    {
        return 1;
    }

    @ConfigSection(
            name = "Overlay",
            description = "Overlay display settings",
            position = 02
    )
    String overlaySection = "overlay";

    @ConfigItem(
            keyName = "backgroundColor",
            name = "Overlay background color",
            description = "Background color of the censor overlay",
            position = 3,
            section = overlaySection
    )
    default Color backgroundColor()
    {
        return new Color(122, 131, 123, 255);
    }

    @ConfigItem(
            keyName = "borderColor",
            name = "Border color",
            description = "Color of the censor overlay border",
            position = 4,
            section = overlaySection
    )
    default Color borderColor()
    {
        return new Color(102, 26, 26, 255);
    }

    @ConfigItem(
            keyName = "drawBorder",
            name = "Draw border",
            description = "Draw a border around the censor overlay",
            position = 5,
            section = overlaySection
    )
    default boolean drawBorder()
    {
        return true;
    }

    @ConfigItem(
            keyName = "drawText",
            name = "Draw text",
            description = "Draw text on top of the censor overlay",
            position = 6,
            section = overlaySection
    )
    default boolean drawText()
    {
        return true;
    }

    @ConfigItem(
            keyName = "censorText",
            name = "Censor text",
            description = "The text that will be drawn on top of your censor overlay",
            position = 7,
            section = overlaySection
    )
    default String censorText()
    {
        return "???";
    }

    @ConfigItem(
            keyName = "textColor",
            name = "Text color",
            description = "Color of the ??? text",
            position = 8,
            section = overlaySection
    )
    default Color textColor()
    {
        return new Color(59, 255, 68, 255);
    }
}

package com.sanitysaver;
import net.runelite.api.*;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.*;
import javax.inject.Inject;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;

public class SanitySaverItemOverlay extends WidgetItemOverlay
{
    private final Map<Integer, BufferedImage> spriteCache = new HashMap<>();

    private final Client client;
    private final SanitySaverConfig config;

    @Inject
    public SanitySaverItemOverlay(Client client, SanitySaverConfig config)
    {
        this.client = client;
        this.config = config;

        showOnInventory();
        showOnBank();
        showOnEquipment();
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem itemWidget)
    {
        int quantity = itemWidget.getQuantity(); 
        if (!shouldCensor(itemId, quantity)) 
        { 
            return; 
        }

        Rectangle bounds = itemWidget.getCanvasBounds(); 
        int x = bounds.x; 
        int y = bounds.y; 
        int width = bounds.width; 
        int height = 10;

        BufferedImage cached = spriteCache.get(itemId);
        if (cached != null)
        {
            graphics.drawImage(cached, x, y, bounds.width, bounds.height, null);
        }

        graphics.setColor(config.backgroundColor()); 
        graphics.fillRect(x, y, width, height); 

        if (config.drawBorder()) 
        { 
            graphics.setColor(config.borderColor());
            graphics.drawRect(x, y, width - 1, height - 1);
        } 

        if (config.drawText()) 
        { 
            String text = config.censorText(); 
            FontMetrics fm = graphics.getFontMetrics(); 
            int textX = x + 2; 
            int textY = y + fm.getAscent() - 1; 
            graphics.setColor(Color.BLACK); 
            graphics.drawString(text, textX + 1, textY + 1); 
            graphics.setColor(config.textColor()); 
            graphics.drawString(text, textX, textY); 
        }
    }

    private boolean shouldCensor(int itemId, int quantity)
    {
        if (quantity < config.minAmount())
            return false;

        String list = config.censoredItems().trim();
        if (list.isEmpty())
            return false;

        ItemComposition comp = client.getItemDefinition(itemId);
        String name = comp.getName().toLowerCase();

        for (String token : list.toLowerCase().split(","))
        {
            token = token.trim();
            if (token.isEmpty())
                continue;

            if (token.equals(String.valueOf(itemId)) || name.contains(token))
                return true;
        }

        return false;
    }

    public void cacheSprite(int itemId, BufferedImage image)
    {
        spriteCache.put(itemId, image);
    }

    public void removeSprite(int itemId)
    {
        spriteCache.remove(itemId);
    }

    public boolean isCached(int itemId)
    {
        return spriteCache.containsKey(itemId);
    }

    public void clearCache()
    {
        spriteCache.clear();
    }
}

package com.sanitysaver;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.PostItemComposition;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.AsyncBufferedImage;


import javax.inject.Inject;

import java.awt.*;
import java.awt.image.BufferedImage;

@Slf4j
@PluginDescriptor(
	name = "Sanity Saver"
)
public class SanitySaverPlugin extends Plugin
{
	@Inject
	private Client client;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ClientThread clientThread;

	@Inject
	private SanitySaverConfig config;

    @Inject
    private SanitySaverItemOverlay itemOverlay;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ConfigManager configManager;

	@Override
	protected void startUp() throws Exception
	{
        itemOverlay.clearCache();
        resetCaches();
        overlayManager.add(itemOverlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
        itemOverlay.clearCache();
        resetCaches();
        overlayManager.remove(itemOverlay);
	}

	@Provides
	SanitySaverConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SanitySaverConfig.class);
	}

    //Ref unidentified-herbs by hex-agon and MoreFillPlugin by UnExploration
    @Subscribe
    public void onPostItemComposition(PostItemComposition event)
    {
        ItemComposition itemComposition = event.getItemComposition();
        int itemId = itemComposition.getId();

        if (!isItemCensored(itemId))
        {
            return;
        }

        if (itemOverlay.isCached(itemId))
        {
            itemComposition.setInventoryModel(-1);
            return;
        }

        AsyncBufferedImage image = itemManager.getImage(itemId);

        image.onLoaded(() ->
        {
            BufferedImage buffered = image.getSubimage(0, 0, image.getWidth(), image.getHeight());
            itemOverlay.cacheSprite(itemId, buffered);

            itemComposition.setInventoryModel(-1);
            resetCaches();
        });
    }

    //Ref unidentified-herbs by hex-agon and MoreFillPlugin by UnExploration
    private void resetCaches() {
        clientThread.invokeLater(() -> {
            client.getItemCompositionCache().reset();
            client.getItemModelCache().reset();
            client.getItemSpriteCache().reset();
        });
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        if (!client.isKeyPressed(KeyCode.KC_SHIFT))
        {
            return;
        }

        if (!event.getOption().equalsIgnoreCase("Examine"))
        {
            return;
        }

        Widget widget = event.getMenuEntry().getWidget();

        if (widget == null || widget.getItemId() <= 0)
        {
            return;
        }

        int itemId = widget.getItemId();

        boolean censored = isItemCensored(itemId);

        String option = censored ? "Uncensor" : "Censor";

        Menu menu = client.getMenu();
        MenuEntry entry = menu.createMenuEntry(-1); // -1 to append at the end
        entry.setOption(option)
                .setTarget(event.getTarget())
                .setType(MenuAction.RUNELITE)
                .onClick(e -> toggleItemCensor(itemId));

    }

    private boolean isItemCensored(int itemId)
    {
        String list = config.censoredItems();
        if (list == null || list.isBlank())
        {
            return false;
        }

        for (String censoredID : list.split(","))
        {
            if (censoredID.trim().equals(String.valueOf(itemId)))
            {
                return true;
            }
        }

        return false;
    }

    private void toggleItemCensor(int itemId)
    {
        String id = String.valueOf(itemId);
        String current = config.censoredItems();

        StringBuilder censoredIDList = new StringBuilder();

        boolean removed = false;

        if (current != null && !current.isBlank())
        {
            for (String censoredID : current.split(","))
            {
                censoredID = censoredID.trim();
                if (censoredID.isEmpty())
                {
                    continue;
                }

                if (censoredID.equals(id))
                {
                    removed = true;
                    itemOverlay.removeSprite(itemId);
                    continue;
                }

                if (censoredIDList.length() > 0)
                {
                    censoredIDList.append(", ");
                }
                censoredIDList.append(censoredID);
            }
        }

        if (!removed)
        {
            if (censoredIDList.length() > 0)
            {
                censoredIDList.append(", ");
            }
            censoredIDList.append(id);
        }

        configManager.setConfiguration(
                "sanitysaver",
                "censoredItems",
                censoredIDList.toString()
        );

        resetCaches();
    }
}

